const tFor=zh=>copy[zh?'zh':'en'];
const fmt=(n,zh)=>new Intl.NumberFormat(zh?'zh-HK':'en-HK',{maximumFractionDigits:0}).format(Math.round(n));
const money=(n,zh)=>'HK$ '+fmt(n,zh);
export function selectedPlan(v){return plans.find(p=>p.id===v.planId)||plans[0];}
export function parameters(v){return normalizeExplore(v,selectedPlan(v).rate);}
export function plannerLabel(c){return tFor(c.lang!=='en').tab;}
function field(t,name,value,min,max,unit='HK$',step='1',required=false){return `<div><label for="budget-${name}">${t[name]}</label><div class="input-wrap">${unit==='HK$'?'<span class="unit">HK$</span>':''}<input id="budget-${name}" name="${name}" type="number" inputmode="decimal" min="${min}" max="${max}" step="${step}" value="${value}"${required?' required':''}>${unit!=='HK$'?`<span class="unit">${unit}</span>`:''}</div></div>`;}
export function plannerPanel(c){
 const zh=c.lang!=='en',t=tFor(zh);
 return `<div class="explore-panel" data-panel="budget" id="budget-panel"><div class="explore-heading"><span class="step-tag">01</span><div><h2>${t.title}</h2><p class="small">${t.intro}</p></div></div><form id="budget-form" class="explore-intake"><div class="primary-inputs">${field(t,'savings',2500000,0,1e9,'HK$','1',true)}${field(t,'income',60000,1,1e8,'HK$','1',true)}</div><p class="small">${t.sample}</p><input type="hidden" name="months" value="360"><details class="assumption-details"><summary>${t.adjust}</summary><div class="fields"><div><label for="budget-planId">${t.plan}</label><select id="budget-planId" name="planId">${plans.map(p=>`<option value="${p.id}">${zh?p.bankZh:p.bank} · ${p.type} · ${p.rate.toFixed(2)}%${p.cap?zh?' 封頂情境':' cap scenario':''}</option>`).join('')}<option disabled>${t.employee}</option></select></div>${field(t,'debts',0,0,1e8)}${field(t,'reserveMonths',6,0,24,t.monthUnit)}${field(t,'comfortDsr',35,10,50,'%','1')}${field(t,'agencyPct',1,0,5,'%','0.1')}${field(t,'legal',10000,0,1e8)}${field(t,'other',5000,0,1e8)}</div><p class="small">${t.assumptions}</p></details><div class="price-explorer"><div class="slider-heading"><label for="budget-price">${t.slider}</label><output id="budget-price-label" for="budget-price"></output></div><input id="budget-price" name="price" type="range" min="100000" max="15000000" step="50000" value="6000000" aria-describedby="budget-price-help"><p class="small" id="budget-price-help">${t.sliderHelp}</p></div></form><div id="budget-result" class="explore-results" role="region" aria-label="${t.tab}"></div><section class="dream-section" id="dream-house"><div class="explore-heading"><span class="step-tag">⌂</span><div><h2>${t.dream}</h2><p class="small">${t.dreamIntro}</p></div></div><form id="dream-form" class="dream-filters">${[['region',[["Hong Kong",t.hki],["Kowloon",t.kl],["New Territories",t.nt]]],['district',[...new Map(listings.filter(r=>!r.excluded).map(r=>[r.district,zh?r.districtZh:r.district])).entries()]],['estate',listings.filter(r=>!r.excluded).map(r=>[r.id,zh?r.estateZh:r.estate])],['bedrooms',[['0',t.studio],['1',zh?'1 房':'1 bedroom'],['2','2 '+t.rooms],['3','3 '+t.rooms]]]].map(([key,options])=>`<div><label for="dream-${key}">${t[key]}</label><select id="dream-${key}" name="${key}"><option value="all">${t.all}</option>${options.map(([value,label])=>`<option value="${esc(value)}">${esc(label)}</option>`).join('')}</select></div>`).join('')}</form><div id="dream-result"></div><p class="small">${t.snapshot}</p><details class="landreg-note"><summary>${t.lr}</summary><p class="small">${t.lrText}</p><a class="small" href="https://www.landreg.gov.hk/en/services/our_services.htm">${t.lrLink} ↗</a></details></section></div>`;
}
export function prepareExplore(form,reset=false){
 const v=Object.fromEntries([...new FormData(form)].map(([k,x])=>[k,k==='planId'?x:Number(x)]));
 const p=parameters(v),slider=form.elements.namedItem('price');
 const ceiling=purchaseCeiling(p),maximum=purchaseCeiling(p,50);
 slider.max=String(Math.max(1000000,Math.ceil(maximum*1.35/50000)*50000));
 if(reset||!form.dataset.initialized){slider.value=String(Math.max(100000,Math.floor(ceiling/50000)*50000));form.dataset.initialized='true';}
 const price=Number(slider.value),status=assessPrice(price,p).status;
 slider.style.setProperty('--slider-color',status==='green'?'#1a5143':status==='amber'?'#a65b1b':'#ad3c31');
 const zh=document.documentElement.lang==='zh-Hant';
 document.querySelector('#budget-price-label').textContent=money(price,zh);slider.setAttribute('aria-valuetext',money(price,zh));
}
export function plannerResult(v,zh){
 const t=tFor(zh),plan=selectedPlan(v),p=parameters(v),a=assessPrice(v.price,p),ceiling=purchaseCeiling(p),maximum=purchaseCeiling(p,50);
 const metric=(label,value)=>`<div class="metric"><dt>${label}</dt><dd>${value}</dd></div>`;
 return `<div class="budget-overview"><div><div class="eyebrow">${t.comfortable}</div><div class="big-number">${money(ceiling,zh)}</div></div><div class="ceiling-note">${t.maximum}<strong>${money(maximum,zh)}</strong><span>${p.months/12} ${t.years} · ${plan.bank} ${plan.type} · ${p.rate.toFixed(2)}%</span></div></div><div class="affordability-banner ${a.status}" role="status"><strong>${a.status==='green'?'✓ ':a.status==='amber'?'! ':'× '}${t[a.status]}</strong><span>${t.statusCash}${a.cashGap>.01?' '+t.cashGap+': '+money(a.cashGap,zh):''}${a.monthly>a.maximumPayment+.01?' '+t.incomeGap+'.':''}</span></div><dl class="metrics explore-metrics">${metric(t.monthly,money(a.monthly,zh))}${metric(t.loan,money(a.loanNeeded,zh))}${metric(t.fees,money(a.fees.total,zh))}${metric(t.buffer,money(p.reserve,zh))}${metric(t.incomeRatio,a.dsr.toFixed(1)+'%')}${metric(t.stress,money(a.higherPayment,zh))}</dl><h3>${t.termTitle}</h3><p class="small">${t.termNote}</p><div class="term-options">${exploreOptions(p).map(o=>`<button type="button" class="term-card ${o.months===p.months?'chosen':''}" data-term="${o.months}" aria-pressed="${o.months===p.months}"><span>${o.months/12} ${t.years}</span><strong>${money(o.price,zh)}</strong><small>${t.budget}</small><small>${money(assessPrice(v.price,{...p,months:o.months}).monthly,zh)} ${t.perMonth} · ${t.atPrice}</small><b>${o.months===p.months?t.selected:t.useTerm}</b></button>`).join('')}</div><div class="assumption-grid"><details><summary>${t.feeTitle}</summary><dl class="fee-breakdown">${[[t.duty,a.fees.duty],[t.agency,a.fees.agency],[t.legalLabel,a.fees.legal],[t.otherLabel,a.fees.other]].map(([name,value])=>`<div><dt>${name}</dt><dd>${money(value,zh)}</dd></div>`).join('')}</dl><p class="small">${t.feeNote}</p><a class="small" href="${dutySource}">IRD ↗</a> · <a class="small" href="${commissionSource}">EAA ↗</a></details><details><summary>${t.rateTitle} · ${plan.bank} ${plan.type} ${p.rate.toFixed(2)}%</summary><p class="small">${t.formula}: ${esc(plan.formula)}<br>${t.prime}: ${plan.prime.toFixed(2)}%<br>${t.primeEffective}: ${plan.primeDate||t.notPublished}<br>${t.document}: ${plan.documentDate}<br>${t.checked}: ${checkedOn}</p><p class="small">${t.rateNote}</p><a class="small" href="${plan.source}">${t.termsLink} ↗</a><br><a class="small" href="${plan.reference}">${t.referenceLink} ↗</a></details></div><p class="small">${t.notApproval}</p><button type="button" class="next-step" data-use-budget ${!a.feasible||a.loanNeeded<1?'disabled':''}>${t.next} →</button><p class="small">${t.nextNote}</p>`;
}
export function matchingListings(rows,price,filters={}){
 return rows.filter(r=>!r.excluded&&r.price<=price&&['region','district'].every(k=>!filters[k]||filters[k]==='all'||r[k]===filters[k])&&(!filters.estate||filters.estate==='all'||r.id===filters.estate)&&(!filters.bedrooms||filters.bedrooms==='all'||r.bedrooms===Number(filters.bedrooms)));
}
export function dreamResult(v,zh,filters){
 const t=tFor(zh),p=parameters(v),candidates=matchingListings(listings,v.price,filters);
 const chosen=[];const add=(r,why)=>{if(r&&!chosen.some(c=>c.id===r.id))chosen.push({...r,why});};
 add([...candidates].sort((a,b)=>a.price-b.price)[0],'whyLow');
 add([...candidates].sort((a,b)=>b.sqft-a.sqft)[0],'whySpace');
 add([...candidates].sort((a,b)=>b.price-a.price)[0],'whyNear');
 for(const r of [...candidates].sort((a,b)=>b.price-a.price)){if(chosen.length>=3)break;add(r,'whyNear');}
 if(!chosen.length)return `<div class="empty-listings"><p>${t.empty}</p><a href="https://www.28hse.com/en/buy/apartment">${t.browse} ↗</a></div>`;
 return `<div class="listing-cards">${chosen.map(r=>{const a=assessPrice(r.price,p);return `<article class="listing-card"><div class="listing-why">${t[r.why]}</div><span class="affordability-chip ${a.status}">${t[a.status]}</span><h3>${esc(zh?r.estateZh:r.estate)}</h3><p>${esc(zh?r.districtZh:r.district)}</p><strong class="listing-price">${money(r.price,zh)}</strong><span class="small">${t.asking}</span><p class="layout-summary">${r.bedrooms===0?t.studio:r.bedrooms+' '+(!zh&&r.bedrooms===1?'bedroom':t.rooms)} · ${r.sqft} ${t.area}</p><p>${money(a.monthly,zh)} ${t.perMonth} · ${p.months/12} ${t.years}</p><p class="small">${t.listingDate}: ${r.updated}<br>${t.listingChecked}: ${r.checkedOn}</p><a href="${r.source}">${t.view} ↗</a></article>`;}).join('')}</div>`;
}
